    font-family: inherit;
    transition: border-color 0.2s, box-shadow 0.2s;
}

input:hover {
    border-color: #555;
}

input:focus {
    outline: none;
    border-color: #0066cc;
    box-shadow: 0 0 0 3px rgba(0, 102, 204, 0.2);
}

input[aria-invalid="true"] {
    border-color: #ff6b6b;
}

input[aria-invalid="true"]:focus {
    box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.2);
}

.helper-text {
    font-size: 0.85rem;
    color: #888;
    margin-top: 4px;
}

.validation-message {
    font-size: 0.85rem;
    color: #ff8787;
    min-height: 1.2em;
    margin-top: 2px;
    display: none;
}

.validation-message.show {
    display: block;
}

.submit-button {
    padding: 12px 24px;
    background-color: #0066cc;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s, box-shadow 0.2s;
    margin-top: 12px;
}

.submit-button:hover {
    background-color: #0052a3;
}

.submit-button:active {
    background-color: #003d7a;
}

