+class ContactForm {
+    constructor() {
+        this.form = document.getElementById('contactForm');
+        this.fullNameInput = document.getElementById('fullName');
+        this.emailInput = document.getElementById('email');
+        this.phoneInput = document.getElementById('phone');
+        this.successMessage = document.getElementById('successMessage');
+
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        this.fullNameInput.addEventListener('blur', () => this.validateFullName());
+        this.emailInput.addEventListener('blur', () => this.validateEmail());
+        this.phoneInput.addEventListener('blur', () => this.validatePhone());
+    }
+
+    validateFullName() {
+        const value = this.fullNameInput.value.trim();
+        const errorEl = document.getElementById('fullNameError');
+        const isValid = value.length > 0;
+
+        if (!isValid) {
+            this.setFieldError(this.fullNameInput, errorEl, 'Full name is required');
+        } else {
+            this.clearFieldError(this.fullNameInput, errorEl);
+        }
+
+        return isValid;
+    }
+
+    validateEmail() {
+        const value = this.emailInput.value.trim();
+        const errorEl = document.getElementById('emailError');
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        let isValid = true;
+        let errorMessage = '';
+
+        if (value.length === 0) {
+            isValid = false;
+            errorMessage = 'Email address is required';
+        } else if (!emailRegex.test(value)) {
+            isValid = false;
+            errorMessage = 'Please enter a valid email address (e.g., name@example.com)';
+        }
+
+        if (!isValid) {
+            this.setFieldError(this.emailInput, errorEl, errorMessage);
+        } else {
+            this.clearFieldError(this.emailInput, errorEl);
+        }
+
+        return isValid;
+    }
+
+    validatePhone() {
+        const value = this.phoneInput.value.trim();
+        const errorEl = document.getElementById('phoneError');
+
+        if (value.length === 0) {
+            this.clearFieldError(this.phoneInput, errorEl);
+            return true;
+        }
+
+        const phoneRegex = /^[\d\s\-()+]+$/;
+        const hasDigits = /\d/.test(value);
+        const isValid = phoneRegex.test(value) && hasDigits && value.length >= 10;
+
+        if (!isValid) {
+            this.setFieldError(this.phoneInput, errorEl, 'Please enter a valid phone number');
+        } else {
+            this.clearFieldError(this.phoneInput, errorEl);
+        }
+
+        return isValid;
+    }
+
+    setFieldError(input, errorEl, message) {
+        input.setAttribute('aria-invalid', 'true');
+        errorEl.textContent = message;
+        errorEl.classList.add('show');
+    }
+
+    clearFieldError(input, errorEl) {
+        input.setAttribute('aria-invalid', 'false');
+        errorEl.textContent = '';
+        errorEl.classList.remove('show');
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+
+        const isFullNameValid = this.validateFullName();
+        const isEmailValid = this.validateEmail();
+        const isPhoneValid = this.validatePhone();
+
+        if (isFullNameValid && isEmailValid && isPhoneValid) {
+            this.submitForm();
+        } else {
+            const firstInvalidField = document.querySelector('[aria-invalid="true"]');
+            if (firstInvalidField) {
+                firstInvalidField.focus();
+            }
+        }
+    }
+
+    submitForm() {
+        const formData = {
+            fullName: this.fullNameInput.value.trim(),
+            email: this.emailInput.value.trim(),
+            phone: this.phoneInput.value.trim(),
+        };
+
+        console.log('Form submitted:', formData);
+
+        this.form.reset();
+        this.clearFieldError(this.fullNameInput, document.getElementById('fullNameError'));
+        this.clearFieldError(this.emailInput, document.getElementById('emailError'));
+        this.clearFieldError(this.phoneInput, document.getElementById('phoneError'));
+
+        this.successMessage.textContent = 'Thank you! Your message has been sent successfully.';
+        this.successMessage.classList.add('show');
+        this.successMessage.setAttribute('aria-hidden', 'false');
+
+        setTimeout(() => {
+            this.successMessage.classList.remove('show');
+            this.successMessage.setAttribute('aria-hidden', 'true');
+        }, 5000);
+
+        this.fullNameInput.focus();
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactForm();
+});
+
')

